  "02-04": {"t": "«Лиса, заяц и петух» («Заюшкина избушка»)", "d": "Лиса выгоняет зайца из лубяной избушки, и прогнать её не могут ни собаки, ни медведь, ни бык, а только петух с косой."},
  "02-05": {"t": "«Кощей Бессмертный»", "d": "Смерть Кощея спрятана на конце иглы, игла в яйце, яйцо в утке, утка в зайце, а заяц заперт в сундуке."},
  "02-06": {"t": "«Журавль и цапля»", "d": "Журавль и цапля сватаются друг к другу по очереди, всякий раз передумывают и ходят свататься до сих пор."},
  "02-07": {"t": "«Медведь — липовая нога»", "d": "Медведь с отрубленной лапой ладит себе липовую ногу и идёт ночью по селу к старику со старухой с песней «скырлы, скырлы»."},
  "02-08": {"t": "«Лиса и рак»", "d": "Рак вызывает лису бегать наперегонки, цепляется клешнями ей за хвост и на финише оказывается впереди неё."},
  "02-09": {"t": "«Бобовое зёрнышко»", "d": "Петушок давится бобовым зёрнышком, и курочка бежит за маслицем по длинной цепочке от хозяйки к корове и дальше."},
  "02-10": {"t": "«Пузырь, соломинка и лапоть»", "d": "Соломинка ложится мостиком через ручей, лапоть ступает по ней и тонет, а пузырь хохочет, пока не лопается."},
  "02-11": {"t": "«Как мужик гусей делил»", "d": "Мужик делит одного жареного гуся на барина, барыню, двух сыновей и двух дочек так, что себе оставляет больше всех."},
  "02-12": {"t": "«Поди туда — не знаю куда, принеси то — не знаю что»", "d": "Стрелец Андрей приносит царю «то, не знаю что» — невидимого слугу свата Наума, который сам накрывает столы."},
  "02-13": {"t": "«Война грибов»", "d": "Гриб-боровик созывает грибы на войну, и все отказываются по очереди, пока не соглашаются одни дружные грузди."},
  "02-14": {"t": "«Шемякин суд»", "d": "Бедняк показывает судье Шемяке камень, завёрнутый в платок, а судья принимает его за взятку и решает все три дела в его пользу."},
  "02-15": {"t": "«Два Мороза», обработка К. Д. Ушинского", "d": "Мороз гонится за мужиком с топором и проигрывает, потому что чем крепче мороз, тем жарче тот рубит дрова."},
  "02-16": {"t": "«Повесть о Ерше Ершовиче»", "d": "Лещ с рыбами судится с Ершом Ершовичем за Ростовское озеро, и эта сказка-сатира ходила в рукописях ещё в XVII веке."},
  "02-17": {"t": "«Никита Кожемяка»", "d": "Никита Кожемяка в сердцах рвёт двенадцать воловьих кож, а потом запрягает змея в соху и пропахивает борозду до самого моря."},
  "02-18": {"t": "«Царевна Несмеяна»", "d": "Царь обещает Несмеяну в жёны тому, кто её рассмешит, и это удаётся простому работнику, а не заморским царевичам."},
  "02-19": {"t": "«Сказка о молодильных яблоках и живой воде»", "d": "Иван-царевич добывает отцу молодильные яблоки и живую воду, а старшие братья отнимают добычу и сбрасывают его в пропасть."},
  "02-20": {"t": "«Соль»", "d": "Иван-дурак привозит в заморское царство, где не знают соли, целый корабль соли и увозит оттуда царскую дочь."},
  "02-21": {"t": "«Горе»", "d": "Бедный брат хитростью запирает своё Горе под тяжёлым камнем, и с того дня в его доме наконец заводится добро."},
  "02-22": {"t": "«Крылатый, мохнатый да масляный»", "d": "Воробей, мышка и блин живут одной избушкой, пока не меняются работой, и блина в лесу тут же съедает лиса."},
  "02-23": {"t": "«Солдат и смерть»", "d": "Отслуживший солдат загоняет в свою торбу целую ораву чертей, а потом обманом сажает туда же саму Смерть."},
  "02-24": {"t": "«Иван Быкович»", "d": "Иван Быкович рождается от коровы, которая доела объедки золотого ерша, в один день с двумя царскими сыновьями."},
  "02-25": {"t": "«Белая уточка»", "d": "Ведьма оборачивает молодую княгиню белой уточкой, и та выводит двух пушистых утят и третьего, маленького заморыша."},
  "02-26": {"t": "«Волшебное кольцо»", "d": "Мартынка отдаёт последние деньги за спасение собаки и кошки, и потом именно они возвращают ему украденное волшебное кольцо."},
  "02-27": {"t": "«Лиса и тетерев»", "d": "Лиса выманивает тетерева на землю новым указом, что звери с птицами больше не дерутся, а тот спасается, «завидев» охотников."},
  "02-28": {"t": "«Лиса-повитуха»", "d": "Лиса трижды убегает будто бы на крестины и каждый раз тайком лижет общий с волком мёд из кадушки."},
